2	 * Emits `issue.overdue` exactly once per overdue issue.
3	 *
4	 * Owner C implements `@/server/jobs/overdue-issue-job`. `isOverdue()` itself is
5	 * covered by `tests/lib/date.test.ts`.
6	 */
7	import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
8	
9	vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
10	vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
