12	import { subscribe } from "@/lib/event-bus";
13	import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
14	import * as issueRepo from "@/server/repositories/issue-repository";
15	import * as usageRepo from "@/server/repositories/usage-repository";
16	import { toIsoTimestamp } from "@/types/common";
17	import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
18	import type { Tenant } from "../server/_support/fixtures";
19	import type { Unsubscribe } from "@/types/event";
20	
21	let cleanup: () => void;
22	const detachers: Unsubscribe[] = [];
23	
24	const PAST = "2026-01-01T00:00:00.000Z";
25	const FUTURE = "2026-12-31T00:00:00.000Z";
26	const NOW = new Date("2026-06-01T07:00:00.000Z");
27	
28	async function makeTenant(slug: string): Promise<Tenant> {
29	  const tenant = await createTenant(slug);
30	  await usageRepo.recomputeUsage(tenant.org.id);
31	  return tenant;
32	}
33	
34	async function insertIssue(
35	  tenant: Tenant,
36	  overrides: Partial<{ title: string; assigneeId: (typeof tenant.userIds)["member"] | null; dueAt: string | null }>,
37	) {
38	  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
39	  return issueRepo.insertIssue(
40	    issueInput(tenant.org.id, tenant.project.id, overrides),
41	    tenant.userIds.owner,
42	    number,
43	  );
44	}
45	
46	beforeAll(async () => {
47	  cleanup = await useTemporaryDatabase();
48	  resetOverdueTracking();
49	});
50	
51	afterEach(() => {
52	  while (detachers.length > 0) detachers.pop()?.();
53	});
54	
55	afterAll(() => {
56	  cleanup();
57	});
58	
59	describe("jobs/overdue-issue-job", () => {
60	  it("selects only issues whose due date has passed", async () => {
61	    const tenant = await makeTenant("overdue-select");
62	    const overdue = await insertIssue(tenant, { title: "Late", dueAt: PAST });
63	    await insertIssue(tenant, { title: "Not yet", dueAt: FUTURE });
64	
65	    const seen: string[] = [];
66	    detachers.push(
67	      subscribe("issue.overdue", (payload) => {
68	        seen.push(payload.issueId);
69	      }),
70	    );
71	
72	    await runOverdueIssueJob(NOW);
73	
74	    expect(seen).toEqual([overdue.id]);
75	  });
76	
77	  it("ignores issues in a closed status", async () => {
78	    const tenant = await makeTenant("overdue-closed");
79	    const issue = await insertIssue(tenant, { title: "Closed but late", dueAt: PAST });
80	    await issueRepo.setIssueStatus(tenant.org.id, issue.id, "done");
81	
82	    const seen: string[] = [];
83	    detachers.push(
84	      subscribe("issue.overdue", (payload) => {
85	        seen.push(payload.issueId);
86	      }),
87	    );
88	
89	    await runOverdueIssueJob(NOW);
90	
91	    expect(seen).not.toContain(issue.id);
92	  });
93	
94	  it("ignores issues without a due date", async () => {
95	    const tenant = await makeTenant("overdue-no-due");
96	    const issue = await insertIssue(tenant, { title: "No due date", dueAt: null });
97	
98	    const seen: string[] = [];
99	    detachers.push(
