1	/**
2	 * The background job layer: the in-process queue, the scheduler's cadence and
3	 * the two jobs whose behaviour other layers depend on — the overdue scan that
4	 * feeds the notification fan-out, and the trial expiry that moves plans.
5	 */
6	import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
7	
8	vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
9	
10	import { subscribe } from "@/lib/event-bus";
11	import {
12	  drain,
13	  enqueue,
14	  isSchedulerRunning,
15	  pendingCount,
16	  resetQueue,
17	  startScheduler,
18	  stopScheduler,
19	} from "@/server/jobs";
20	import { backoffMs } from "@/server/jobs/webhook-delivery-job";
21	import { shouldRunForOrg } from "@/server/jobs/digest-email-job";
22	import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
23	import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
24	import * as issueRepo from "@/server/repositories/issue-repository";
25	import * as usageRepo from "@/server/repositories/usage-repository";
26	import * as issueService from "@/server/services/issue-service";
27	import { toIsoTimestamp } from "@/types/common";
28	import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
29	import type { Tenant } from "./_support/fixtures";
30	import type { Unsubscribe } from "@/types/event";
31	
32	let cleanup: () => void;
33	let tenant: Tenant;
34	const detachers: Unsubscribe[] = [];
35	
36	const PAST = "2026-01-01T00:00:00.000Z";
37	const NOW = new Date("2026-06-01T07:00:00.000Z");
38	
39	beforeAll(async () => {
40	  cleanup = await useTemporaryDatabase();
41	  tenant = await createTenant("jobs");
42	  await usageRepo.recomputeUsage(tenant.org.id);
43	});
44	
45	afterEach(() => {
46	  while (detachers.length > 0) detachers.pop()?.();
47	  resetQueue();
48	  stopScheduler();
49	});
50	
51	afterAll(() => {
52	  cleanup();
53	});
54	
55	describe("the in-process queue", () => {
56	  it("is idempotent on the job id", () => {
57	    const job = {
58	      id: "usage-rollup:1",
59	      kind: "usage-rollup" as const,
60	      runAt: toIsoTimestamp(NOW),
61	      attempts: 0,
62	      payload: {},
63	    };
64	
65	    enqueue(job);
66	    enqueue(job);
67	
68	    expect(pendingCount()).toBe(1);
69	  });
70	
71	  it("leaves jobs scheduled in the future alone", async () => {
72	    enqueue({
73	      id: "usage-rollup:future",
74	      kind: "usage-rollup",
75	      runAt: toIsoTimestamp(new Date(Date.now() + 3_600_000)),
76	      attempts: 0,
77	      payload: {},
78	    });
79	
80	    await expect(drain()).resolves.toBe(0);
81	    expect(pendingCount()).toBe(1);
82	  });
83	
84	  it("runs a due job and removes it", async () => {
85	    enqueue({
86	      id: "usage-rollup:due",
87	      kind: "usage-rollup",
88	      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
89	      attempts: 0,
90	      payload: {},
91	    });
92	
93	    await expect(drain()).resolves.toBe(1);
94	    expect(pendingCount()).toBe(0);
95	  });
96	});
97	
98	describe("the scheduler", () => {
99	  it("reports whether it is running and stops cleanly", () => {
100	    expect(isSchedulerRunning()).toBe(false);
101	    startScheduler();
102	    expect(isSchedulerRunning()).toBe(true);
103	    stopScheduler();
104	    expect(isSchedulerRunning()).toBe(false);
105	  });
106	});
107	
108	describe("the overdue scan", () => {
109	  it("emits issue.overdue for a past-due open issue, once", async () => {
110	    const issue = await issueService.createIssue(
